/// The browser broker's instruction to act, carrying the evidence that the action was authorized.
/// The broker validates the envelope, consumes or marks the capability in flight, and only then
/// builds a narrower one-use renderer command. The capability reference is consumed in the browser
/// process and is never forwarded onward.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct AuthorizedActionEnvelope {
    /// Wire protocol version in major.minor form. The current value lives only in bip.version.json;
    /// this schema constrains the shape, never the number.
    pub schema_version: ProtocolVersion,
    /// Opaque browser-process dispatch identifier, unique per authorized action envelope.
    pub dispatch_id: DispatchId,
    /// Opaque action identifier owned by the task runtime (domain model section 12.1).
    pub action_id: ActionId,
    /// A digest over a canonical encoding of a message. Used to prove that the action authorized is
    /// exactly the action proposed.
    pub action_digest: ContentDigest,
    /// Reference to a capability record held by the policy broker. The browser process consumes or
    /// marks the capability in flight and never forwards this value to a renderer. It is a reference to
    /// a decision record, not a transferable authority token.
    pub capability_reference: CapabilityReference,
    /// Reference to the approval record that authorized an action. Page text and model text can never
    /// mint one.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub approval_receipt_reference: Option<ApprovalReceiptReference>,
    /// What an action does to a node. Three read-oriented operations activate an ordinary link, move
    /// focus, and bring a target into view. SET_TEXT, SELECT_OPTION, TOGGLE, and SUBMIT_FORM write, and
    /// stopped being reserved wire values at 0.8: the protocol now states what each one does rather
    /// than only that it exists. Each is performed through the platform accessibility action path and
    /// through nothing else, so a submission goes through the control the page offered and the page's
    /// own validation and handlers run; a direct DOM setter, a synthesized event, and a programmatic
    /// form submission are all forbidden, because none of them is an act the page agreed to and none
    /// can be verified against a postcondition (decision 0059). Expressible is not authorized, and four
    /// independent gates keep the write surface shut: the tool that would name it belongs to milestone
    /// M5, every write action class is one no milestone has reached, the browser dispatcher refuses a
    /// form write, and no adapter offers one of these on any node, so a command naming one is refused
    /// for want of an available action. Protocol representation never implies product authorization,
    /// and the requirements and threat-model extension that would open it are \[Open (OD-056)\]. Closed
    /// enumeration: a consumer that receives a value outside this list MUST treat the message as
    /// unsupported and fail closed, and MUST NOT coerce the value to a known member (protocol section
    /// 6.2).
    pub action_type: ActionType,
    /// The complete reference to one observed semantic node. A node identifier is meaningless without
    /// this handle. A handle is ephemeral action input: it may appear in a redacted diagnostic event,
    /// but it is unusable once its epoch or document lifecycle ends and it is never a durable reference
    /// inside stored evidence.
    pub target_handle: NodeHandle,
    /// Typed, bounded, sensitivity-labelled action input, and the one place the protocol says who is
    /// allowed to have authored the bytes that enter a field. A value is either named or carried, never
    /// both: value_reference names a value the browser already holds and is the only form a proposal
    /// may use, while text and option_value carry the bytes themselves and appear only on the narrowed
    /// one-use command the browser builds after it has resolved the reference and spent it. That split
    /// is what makes "the model never authors what enters a field" a shape rule a checker can apply
    /// rather than a convention. An input whose sensitivity classifies it as a credential is refused
    /// outright, by name as well as by value: BIP carries no password, passcode, one-time code,
    /// recovery code, private key, or token value in either direction, and no reference to one either.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub input: Option<ActionInput>,
    /// Monotonically increasing revision within one active page epoch. It advances whenever a mutation
    /// can invalidate a previously observed node, relationship, action precondition, or relevant value.
    /// Revisions from different epochs or frames are not comparable.
    pub required_graph_revision: GraphRevision,
    pub preconditions: Vec<Precondition>,
    pub expected_postconditions: Vec<Postcondition>,
    /// A reading of a monotonic clock in milliseconds. BIP carries no wall-clock timestamps, so a
    /// message cannot leak browsing time across a trust boundary.
    pub absolute_deadline_monotonic_ms: MonotonicMillis,
}

